begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message;end if;end$$;
insert into auth.users(id) values('11250000-0000-4000-8000-000000000001'),('11250000-0000-4000-8000-000000000002'),('11250000-0000-4000-8000-000000000003'),('11250000-0000-4000-8000-000000000004');
insert into public.user_roles(user_id,role) values('11250000-0000-4000-8000-000000000001','professional'),('11250000-0000-4000-8000-000000000004','professional');
insert into public.professional_student_relationships(id,professional_user_id,student_user_id,status,accepted_at) values('11250000-0000-4000-8000-000000000010','11250000-0000-4000-8000-000000000001','11250000-0000-4000-8000-000000000002','active',now());
insert into public.programs(id,professional_user_id,title) values('11250000-0000-4000-8000-000000000060','11250000-0000-4000-8000-000000000001','Programa sintético');
insert into public.program_versions(id,program_id,version_number,weekly_plan,published_at) values('11250000-0000-4000-8000-000000000061','11250000-0000-4000-8000-000000000060',1,'{}',now());
insert into public.program_assignments(id,program_id,version_id,professional_user_id,student_user_id,relationship_id,status) values('11250000-0000-4000-8000-000000000062','11250000-0000-4000-8000-000000000060','11250000-0000-4000-8000-000000000061','11250000-0000-4000-8000-000000000001','11250000-0000-4000-8000-000000000002','11250000-0000-4000-8000-000000000010','active');
insert into public.workout_executions(id,assignment_id,version_id,student_user_id,day_key,status,completed_at,payload) values('11250000-0000-4000-8000-000000000063','11250000-0000-4000-8000-000000000062','11250000-0000-4000-8000-000000000061','11250000-0000-4000-8000-000000000002','monday','completed',now(),'{"workoutId":"legacy-text-id","workoutName":"Treino autorizado","entries":[],"note":"EXEC_PRIVATE"}');
insert into public.workout_sessions(id,user_id,status,prescription_snapshot,completed_at) values('11250000-0000-4000-8000-000000000020','11250000-0000-4000-8000-000000000002','completed','{}',now());
insert into public.workout_session_operations(session_id,user_id,operation_id,session_revision,kind,payload) values('11250000-0000-4000-8000-000000000020','11250000-0000-4000-8000-000000000002','11250000-0000-4000-8000-000000000021',2,'session_completed','{"workout":{"id":"legacy-text-id","entries":[]}}');
insert into public.workout_sessions(id,user_id,status,prescription_snapshot,completed_at) values('11250000-0000-4000-8000-000000000022','11250000-0000-4000-8000-000000000002','completed','{}',now());
insert into public.workout_session_operations(session_id,user_id,operation_id,session_revision,kind,payload) values('11250000-0000-4000-8000-000000000022','11250000-0000-4000-8000-000000000002','11250000-0000-4000-8000-000000000023',2,'session_completed','{"workout":{"id":"legacy-second","entries":[]}}');
insert into public.account_preferences(user_id,preferences) values('11250000-0000-4000-8000-000000000002','{"theme":"light","trainingCheckIns":{"legacy-text-id":{"version":1,"status":"answered","reasons":["time_constraint"],"note":"PRIVATE"}}}');
set local role authenticated;
select set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000002',true);
do $$
declare saved jsonb; data jsonb; reasons jsonb; rec jsonb:='{"version":1,"status":"answered","reasons":["time_constraint"],"note":"PRIVATE"}'; shares jsonb:='[{"relationshipId":"11250000-0000-4000-8000-000000000010","reasons":["time_constraint"]}]';
begin
 saved:=public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000030',null,true);
 perform pg_temp.assert_true(saved->>'note'='PRIVATE','owner saved private note');
 perform public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000030',null,true);
 perform pg_temp.assert_true((select count(*)=1 from public.training_checkins),'idempotent import');
 perform pg_temp.assert_true((select preferences->>'theme'='light' and not (preferences->'trainingCheckIns' ? 'legacy-text-id') from public.account_preferences),'legacy cleanup preserves unrelated settings');
 begin perform public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000031');raise exception 'stale write accepted';exception when serialization_failure then null;end;
 begin perform public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000032',null,true);raise exception 'conflicting legacy accepted';exception when serialization_failure then null;end;
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000003',true);
 perform pg_temp.assert_true((select count(*)=0 from public.training_checkins),'other student cannot read');
 begin perform public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000033');raise exception 'foreign workout accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000001',true);
 perform pg_temp.assert_true((select count(*)=0 from public.training_checkins),'linked professional cannot read private table');
 data:=public.get_professional_insights_context();
 perform pg_temp.assert_true(data->'items'->0->'sharedCheckins'='[]','without consent no reasons');
 perform pg_temp.assert_true(data->'items'->0->'workouts'->0->>'name'='Treino autorizado' and position('EXEC_PRIVATE' in data::text)=0,'authorized minimal workout projection');
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000002',true);
 saved:=public.save_training_checkin('legacy-text-id',rec,1,'11250000-0000-4000-8000-000000000034',shares);
 perform public.save_training_checkin('legacy-second',rec,0,'11250000-0000-4000-8000-000000000050',shares);
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000001',true);
 data:=public.get_professional_insights_context();
 perform pg_temp.assert_true(data->'items'->0->'sharedCheckins'->0->'reasons'='["time_constraint"]','only consented reasons returned');
 perform pg_temp.assert_true(position('PRIVATE' in data::text)=0 and position('"note"' in data::text)=0,'notes never returned');
 perform public.save_professional_insight_state('11250000-0000-4000-8000-000000000010','recurring_time_constraint','episode','["recurring_time_constraint",["legacy-text-id","legacy-second"],null]','reviewed',0);
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000004',true);
 perform pg_temp.assert_true(public.get_professional_insights_context()->'items'='[]','unlinked professional sees no students');
 begin perform public.save_professional_insight_state('11250000-0000-4000-8000-000000000010','recurring_time_constraint','episode','["recurring_time_constraint",["legacy-text-id"],null]','reviewed',0);raise exception 'foreign state accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000002',true);
 saved:=public.save_training_checkin('legacy-text-id',rec,2,'11250000-0000-4000-8000-000000000035','[]');
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000001',true);
 data:=public.get_professional_insights_context();
 perform pg_temp.assert_true(jsonb_array_length(data->'items'->0->'sharedCheckins')=1 and data->'items'->0->'sharedCheckins'->0->>'workoutId'='legacy-second','partial revocation immediate');
 perform pg_temp.assert_true(position('legacy-text-id' in (data->'items'->0->'states')::text)=0 and data->'items'->0->'states'->0->>'status'='reviewed','partial revocation redacts stored associations while preserving review');
 perform pg_temp.assert_true(not has_table_privilege('authenticated','public.professional_insight_states','SELECT'),'revoked reason tracking does not leak prior evidence');
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000002',true);
 begin perform public.save_training_checkin('legacy-text-id','{"version":1,"status":"answered","reasons":["pain_or_discomfort"],"note":""}',3,'11250000-0000-4000-8000-000000000039','[{"relationshipId":"11250000-0000-4000-8000-000000000010","reasons":["pain_or_discomfort"]}]');raise exception 'sensitive consent not enforced';exception when invalid_parameter_value then null;end;
 saved:=public.save_training_checkin('legacy-text-id',rec,3,'11250000-0000-4000-8000-000000000036',shares);
 perform public.revoke_professional_relationship('11250000-0000-4000-8000-000000000010');
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000001',true);
 perform pg_temp.assert_true(public.get_professional_insights_context()->'items'='[]','ended relationship immediately removes context');
 perform pg_temp.assert_true(not has_table_privilege('authenticated','public.professional_insight_states','SELECT'),'state cannot bypass ended relationship');
 perform set_config('request.jwt.claim.sub','11250000-0000-4000-8000-000000000002',true);
 saved:=public.save_training_checkin('legacy-text-id',rec,4,'11250000-0000-4000-8000-000000000041','[{"relationshipId":"11250000-0000-4000-8000-000000000010","reasons":[]}]');
 perform pg_temp.assert_true(saved->>'note'='PRIVATE','ended cycle permits private edit and explicit revocation');
 begin perform public.save_training_checkin('legacy-text-id',rec,5,'11250000-0000-4000-8000-000000000042',shares);raise exception 'ended grant accepted';exception when sqlstate 'PCK01' then null;end;
 perform pg_temp.assert_true(not exists(select 1 from public.training_checkin_shares where checkin_id=(saved->>'id')::uuid and revoked_at is null and cardinality(shared_reasons)>0),'rejected ended grant never confers access');
 saved:=public.save_training_checkin('legacy-text-id','{"version":1,"status":"removed"}',5,'11250000-0000-4000-8000-000000000040');
 perform pg_temp.assert_true(saved->>'note'='' and saved->'reasons'='[]','removed record discards note and reasons');
 saved:=public.save_training_checkin('legacy-text-id',rec,0,'11250000-0000-4000-8000-000000000030',null,true);
 perform pg_temp.assert_true(saved->>'status'='removed','retrying an old import cannot resurrect a response');
end$$;
reset role;
